from pathlib import Path
import json,hashlib,re
from datetime import datetime,timezone
R=Path(__file__).resolve().parents[1];J=R/'judge/kongguan';A=J/'acceptance';T=R/'tasks/kongguan'
def read(p):return json.loads(p.read_text(encoding='utf8'))
def write(p,d):p.write_text(json.dumps(d,ensure_ascii=False,indent=2),encoding='utf8')
def main():
 record=next(x for x in read(R/'data/preparation/catalogue.json')['records'] if x['record_id']=='base664:0029');write(J/'source/catalogue-record.json',record)
 provenance=read(T/'provenance.json');actual={p.relative_to(T/'mirror').as_posix():p for p in (T/'mirror').rglob('*') if p.is_file()};assert set(actual)=={x['path'] for x in provenance['files']};assert all(hashlib.sha256(actual[x['path']].read_bytes()).hexdigest()==x['sha256'] for x in provenance['files'])
 semantic=[]
 for name,p in actual.items():
  if name=='tools/base64/index.html':semantic.append({'path':name,'status':'new_local_standard_utility'});continue
  original=(J/'source/current'/name).read_bytes();expected=original
  if name.endswith(('.html','.js','.css')):
   s=re.sub(r'<script[^>]+cloudflareinsights[\s\S]*?</script>','',original.decode('utf8'))
   if name=='s1coffin/search/search-data.js':s=s.replace("target: 'https://base64.us/'","target: '/tools/base64/index.html'")
   expected=s.encode('utf8')
  assert expected==p.read_bytes(),name;semantic.append({'path':name,'status':'matches_original_after_declared_compatibility_only'})
 write(J/'source/game-logic-equivalence.json',{'files':semantic,'game_logic_changed':False,'utility_substitution':'Only external Base64 helper appearance/code differs; RFC4648 foo encode/decode and malformed input checked in both independent deployments.'})
 ui=read(A/'ui-report.json');assert not ui.get('failure') and not ui['errors'] and not ui['missing'];mail=read(A/'mail-branches-report.json');assert len(mail)==9 and all(x.get('passed') for x in mail);side=read(A/'side-branches-report.json');assert all(not x.get('failure') and not x['errors'] for x in side['mystery_variants']);assert len(side['review_negatives'])==2
 reports={m:read(A/f'exam-{m}-report.json') for m in ['good','bad','quit']};assert all(not v.get('failure') and not v['errors'] for v in reports.values());assert not reports['bad']['missing'] and not reports['quit']['missing']
 questions=['q5','q6','q7','q8','q9','q10','q11','q16','q18','q19','q21','q27','q29','q31'];checks={}
 for q in questions:
  hook='exam_'+q;positive=any(s['values'].get(hook) is True for s in reports['good']['actions']);negative=any(s['values'].get(hook) is False for m in ['bad','quit'] for s in reports[m]['actions'] if s['label'].startswith(q+' ') or s['label'].startswith(q+' rejected'));assert positive and negative,q;checks[q]={'native_ui_positive':positive,'native_ui_negative':negative}
 endings=[]
 for mode in ['good','bad']:
  for route in ['A1','B1','B2']:
   d=read(A/f'ending-{mode}-{route}-report.json');assert not d.get('failure') and not d['errors'] and not d['missing'];endings.append({'mode':mode,'route':route,'ending':d['ending'],'score':d['score']})
 for route in ['ordinary','detective']:
  d=read(A/f'failure-{route}-report.json');assert not d.get('failure') and not d['errors'] and d['score']['ending_tier']=='bad' and d['fresh_context_reset'];endings.append({'ending':route,'score':d['score']})
 delivery=read(A/'independent-delivery.json');assert len(delivery)==2
 for d in delivery:assert hashlib.sha256((R/d['archive']).read_bytes()).hexdigest()==d['sha256']
 audit={'record_id':'base664:0029','task_id':'kongguan','completed_utc':datetime.now(timezone.utc).isoformat(),'resources_unique_files':len(actual),'original_game_files':len(actual)-1,'formal_endings':5,'reasoning_points':20,'checkpoints':21,'aggregate_gate':'exam_all_correct duplicates the individual graded answers only as a necessary route gate, not an independent puzzle','graded_questions':checks,'ending_route_matrix':endings,'mail_branch_cases':9,'mail_branch_coverage':'All first options and all second/final options. First-email choices converge to the same incoming response; branch-edge coverage avoids redundant Cartesian replays of source-identical continuations. Both Zhou first×reply combinations tested.','mystery_coverage':'Normal timed 60-second request plus secret520 shortcut; all alternatives at each of the three branching questions; wrong/existing employee add requests rejected.','ordinary_exploration':'Photos, news, project/paper/document reading, notepad, and collection achievements are source-audited retrieval/collection, not additional reasoning checkpoints. Meta achievement ending_all and sequel prelude are not extra formal endings.','reset':'Fresh context clears all game state; authored rewind preserves investigation/ending history, clears exam when specified; quiz exit returns desktop without a result.','judge':'Privileged read-only state predicates sampled by separate harness.judge.Judge; ending requires actual rendered matching title+matching unlock, excludes review; no answer injection or calling game functions.','resolved_issues':[{'issue':'HTTP client receives403','resolution':'Edge loads original public site and same-origin fetch200; all resources captured via browser.'},{'issue':'Dynamically constructed /music/end01.mp3 initially404 during exam-to-funeral transition','resolution':'Captured original audio; repeated all6 funeral combinations and both independent ZIP probes have no404. Original good-exam report retained transparently; exam logic/assets unchanged.'},{'issue':'Concurrent initial page loads occasionally lost script dependencies','resolution':'Staggered/sequential exact-case retries passed; failed email attempts retained under prior_attempt.'}],'adaptation_risks':['External base64.us tool replaced by local standard UTF-8 encoder/decoder; same encoding semantics, different appearance.','Screenshot observation cannot hear the farewell recording. Its open event, not audio comprehension, triggers the timed contact; all graded answers also have text/visual evidence.','No paid/model API evaluation or model-solvability claim. Windows Python3.11/Edge only; no cross-OS claim.'],'compatibility_evidence':'judge/kongguan/source/compatibility.diff','package_acceptance':delivery}
 write(J/'acceptance-summary.json',audit)
 result={'record_id':'base664:0029','task_id':'kongguan','title':'多维实体：空棺（又名多维尸体·空棺）','status':'prepared_with_documented_local_utility_adapter','resource_status':'complete_local_browser_captured_165_original_files_plus_standard_base64_utility','integration_status':'L1_ready_8821_fresh_context_reset','content_status':'all_reasoning_forms_14_graded_exam_questions_5_endings_and_branch_edges_audited','judge_status':'21_checkpoints_20_reasoning_points_plus_aggregate_perfect_exam_gate; positive_negative_and_review_exclusion_verified','flow_status':'normal_UI_complete_5_endings_6_funeral_combinations_9_mail_cases_all_mystery_alternatives_quit_reset','delivery_status':'resources_and_prepared_ZIPs_independently_extracted_deployed_and_hash_checked_on8822_8823','runtime_layer':'L1','account_requirement':'none','ready_for_local_execution':True,'ready_for_formal_scoring':True,'formal_scoring_scope':'Frozen local adaptation; original puzzle logic unchanged. Tool appearance substitution and audio observation limitation documented for dataset suitability review.','resources_bundle':'packs/kongguan.resources.zip','evaluation_bundle':'packs/kongguan.prepared.zip','bundle_hashes':{d['kind']:d['sha256'] for d in delivery},'evidence':['judge/kongguan/acceptance-summary.json','judge/kongguan/checkpoint-spec.json','judge/kongguan/source/catalogue-record.json','judge/kongguan/source/access-audit.json','judge/kongguan/source/resource-inventory.json','judge/kongguan/source/game-logic-equivalence.json','judge/kongguan/source/compatibility.diff','tasks/kongguan/provenance.json','judge/kongguan/acceptance/ui-report.json','judge/kongguan/acceptance/exam-route-report.json','judge/kongguan/acceptance/exam-good-report.json','judge/kongguan/acceptance/exam-bad-report.json','judge/kongguan/acceptance/exam-quit-report.json','judge/kongguan/acceptance/mail-branches-report.json','judge/kongguan/acceptance/side-branches-report.json','judge/kongguan/acceptance/independent-delivery.json','judge/kongguan/HANDOFF.md'],'risks':audit['adaptation_risks'],'model_api_calls':0,'paid_services_used':False,'shared_files_modified':False,'working_tree_pushes':0}
 write(R/'data/preparation/results/base664-0029.json',result);print('finalized',len(actual),'files;',len(questions),'graded questions;',len(endings),'ending route checks; two independent bundles')
